'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const passwords = input.slice(1, n + 1);
const frequency = new Map();

for (const password of passwords) {
  frequency.set(password, (frequency.get(password) || 0) + 1);
}

let answer = 0;

for (const password of passwords) {
  const substrings = new Set();

  for (let start = 0; start < password.length; start++) {
    for (let end = start + 1; end <= password.length; end++) {
      substrings.add(password.slice(start, end));
    }
  }

  let accessibleUsers = 0;
  for (const substring of substrings) {
    accessibleUsers += frequency.get(substring) || 0;
  }

  answer += accessibleUsers - 1;
}

console.log(answer.toString());
